private static void bfs(char[][] grid, int x, int y, Set<Integer> depositedPlots) {
    Queue<int[]> queue = new LinkedList<>();
    queue.add(new int[]{x, y});
    depositedPlots.add(x * grid.length + y);
    while (!queue.isEmpty()) {
        int[] curr = queue.remove();
        int currX = curr[0];
        int currY = curr[1];
        if (grid[currX][currY] == '@') {
            grid[currX][currY] = ' ';
            int[] neighbors = getNeighbors(grid, currX, currY);
            for (int[] neighbor : neighbors) {
                if (grid[neighbor[0]][neighbor[1]] == '@' && !depositedPlots.contains(neighbor[0] * grid.length + neighbor[1])) {
                    queue.add(neighbor);
                    depositedPlots.add(neighbor[0] * grid.length + neighbor[1]);
                }
            }
        }
    }
}

private static int[][] getNeighbors(char[][] grid, int x, int y) {
