public int minInsertions(String s) {
    int n = s.length();
    int[][] dp = new int[n][n];

    // dp[i][j] = Minimum number of insertions required to make the substring s[i...j] balanced.
    for (int i = n - 1; i >= 0; i--) {
        dp[i][i] = 0; // Base case: The substring s[i:i + 1] is already balanced.
        for (int j = i + 1; j < n; j++) {
            if (s.charAt(i) == s.charAt(j)) { // s[i] == s[j]
                // Insert a '(' at s[i] or s[j] to make the substring s[i:j + 1] balanced.
                dp[i][j] = Math.min(dp[i + 1][j - 1], dp[i + 1][j]);
            } else if (s.charAt(i) != s.charAt(j)) { // s[i] != s[j]
                // Insert a ')' at s[i] or s[j] to make the substring s[i:j + 1] balanced.
                dp[i][j] = Math.min(dp[i][j - 1], dp[i + 1][j]);
            }
        }
    }

    return dp[0][n - 1]; // The minimum number of insertions required to make the entire string balanced.
}

