public static String longestSubstringNoAdjacentDuplicates(String s) {
    int maxLength = 0;
    int startIndex = 0;
    for (int i = 0; i < s.length(); i++) {
        int currentLength = 1;
        for (int j = i + 1; j < s.length(); j++) {
            if (s.charAt(j) != s.charAt(j - 1)) {
                currentLength++;
            } else {
                break;
            }
        }
        if (currentLength > maxLength) {
            maxLength = currentLength;
            startIndex = i;
        }
    }
    return s.substring(startIndex, startIndex + maxLength);
}

public static String findMostFrequentSubstring(String s, int length) {
    Map<String, Integer> frequencyMap = new HashMap<>();
    for (int i = 0; i <= s.length() - length; i++) {
        String substring = s.substring(i, i + length);
        frequencyMap.put(substring, frequencyMap.getOrDefault(substring, 0) + 1);
    }
    int maxFrequency = 0;
    String mostFrequentSubstring = null;
    for (Map.Entry<String, Integer> entry : frequencyMap.entrySet()) {
        if (entry.getValue() > maxFrequency) {
            maxFrequency = entry.getValue();
            mostFrequentSubstring = entry.getKey();
        }
    }
    return mostFrequentSubstring;
}

public static TreeNode findLowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {
    if (root == null) {
        return null;
    }
    if (root == p || root == q) {
        return root;
    }
    TreeNode leftLCA = findLowestCommonAncestor(root.left, p, q);
    TreeNode rightLCA = findLowestCommonAncestor(root.right, p, q);
    if (leftLCA != null && rightLCA != null) {
        return root;
    }
    return leftLCA != null ? leftLCA : rightLCA;
}

